export async function createCheckout(currency: 'usd' | 'eur' | 'gbp', planId: string) {
  const rates: Record<string, number> = { usd: 1.0, eur: 0.92, gbp: 0.79 };
  const multiplier = rates[currency] || 1.0;
  return { checkoutUrl: `https://checkout.stripe.com/pay/${planId}?cur=${currency}`, rate: multiplier };
}

