export async function batchTenantLookup(db: any, tenantId: string) {
  return await db.batch([
    db.prepare('SELECT * FROM tenants WHERE id = ?').bind(tenantId),
    db.prepare('SELECT * FROM settings WHERE tenant_id = ?').bind(tenantId),
    db.prepare('SELECT * FROM permissions WHERE tenant_id = ?').bind(tenantId)
  ]);
}

